// Generates the API types from the backend OpenAPI document.
// Usage: npm run api:generate (set OPENAPI_URL to read it from another backend).
import { writeFile } from 'node:fs/promises'

import openapiTS, { astToString } from 'openapi-typescript'

const DEFAULT_OPENAPI_URL = 'http://127.0.0.1:8000/openapi.json'
const OUTPUT_PATH = new URL('../src/api/generated/schema.ts', import.meta.url)
const HEADER = `/**
 * This file was auto-generated by openapi-typescript from the Observa backend OpenAPI.
 * Do not make direct changes to the file: regenerate it with \`npm run api:generate\`.
 */

`

const source = process.env.OPENAPI_URL ?? DEFAULT_OPENAPI_URL
const ast = await openapiTS(new URL(source))
await writeFile(OUTPUT_PATH, HEADER + astToString(ast))
console.log(`API types generated from ${source}`)
